/**
 * Tutte le linee di traduzione caricate
 */
protected array $lines = [];

public function __construct($locales)
{
    $this->locales = $locales;
}


/**
 * Restituisce elenco dei locale
 */
public function getLocales()
{
    return $this->locales;
}


/**
 * controlla se un locale è valido
 */
protected function checkLocale($locale)
{
    if (!in_array($locale, $this->locales)) {
        throw new  Exception("Locale missing ".$locale);
    }

    return true;
}


/**
 * Tenta di impostare locale recuperandolo da cartella lingua nell'url
 */
public function setLocale($url)
{
    $urlPath = parse_url($url);
    if (!isset($urlPath['path'])) {
        return null;
    }
    $url = $urlPath['path'];

    $url = explode('/', $url);

    $url = array_key_exists(1, $url) ? $url[1] : null;

    $id = $this->idByPrefix($url);

    if ($id) {
        return $url;
    }

    return null;

